// Page layer — generated by line-matcher from the design. Props in, JSX out; no business logic.
import DealRow from "../component/DealRow.jsx";

export default function DealsPage({
  status,
  error,
  dealCount,
  pipeline,
  avgDeal,
  largest,
  smallest,
  avgMargin,
  weighted,
  syncedAt,
  rows,
  selectedId,
  formValues,
  onEdit,
  onSave,
  onCancel,
}) {
  return (
    <main className="page">
      {status === "loading" && <p className="status">Loading…</p>}
      {error && (
        <p role="alert" className="error">
          {error}
        </p>
      )}
      <header className="header">
        <h1>Deals</h1>
        <p className="meta">
          <span>{dealCount}</span>
          {" deals · pipeline "}
          <span>{pipeline}</span>
          {" · average deal "}
          <span>{avgDeal}</span>
          {" · largest "}
          <span>{largest}</span>
          {" · smallest "}
          <span>{smallest}</span>
          {" · average margin "}
          <span>{avgMargin}</span>
          {" · weighted pipeline "}
          <span>{weighted}</span>
          {" · synced "}
          <span>{syncedAt}</span>
        </p>
      </header>

      <form
        className="card form"
        key={selectedId ?? "new"}
        onSubmit={(e) => {
          e.preventDefault();
          onSave(Object.fromEntries(new FormData(e.currentTarget)));
        }}
      >
        <input name="name" placeholder="Deal" required defaultValue={formValues.name ?? ""} />
        <input
          name="account"
          placeholder="Account"
          required
          defaultValue={formValues.account ?? ""}
        />
        <input
          name="value"
          type="number"
          placeholder="Value (USD)"
          required
          defaultValue={formValues.value ?? ""}
        />
        <input
          name="margin"
          type="number"
          step="0.01"
          placeholder="Margin (0-1)"
          required
          defaultValue={formValues.margin ?? ""}
        />
        <input name="notes" placeholder="Notes" defaultValue={formValues.notes ?? ""} />
        <button type="submit" className="primary">
          Save
        </button>
        <button type="button" onClick={onCancel}>
          Cancel
        </button>
      </form>

      <table className="card table">
        <thead>
          <tr>
            <th>Deal</th>
            <th>Account</th>
            <th>Contact</th>
            <th>Owner</th>
            <th>CSM</th>
            <th>Value</th>
            <th>Margin</th>
            <th>Close</th>
            <th>Stage</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <DealRow key={row.id} row={row} selected={row.id === selectedId} onEdit={onEdit} />
          ))}
        </tbody>
      </table>
    </main>
  );
}
